<!doctype html><html lang="ar" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مولد النماذج الرسمية</title><link rel="stylesheet" href="/app.css"><style>.generator{max-width:1100px;margin:32px auto;padding:24px}.generator nav{display:flex;gap:8px;flex-wrap:wrap}.generator section{margin-top:20px}.generator .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.generator label{display:grid;gap:6px}.generator textarea{min-height:100px}.generator .actions{display:flex;gap:10px;margin-top:18px}.generator [hidden]{display:none!important}@media print{.no-print{display:none!important}.generator{margin:0;max-width:none}}</style></head><body><main class="generator"><header class="heading no-print"><div><p class="eyebrow">القوالب الرسمية المعتمدة</p><h1>مولد النماذج والتقارير</h1><p class="muted">عبئ البيانات ثم احفظ التقرير أو اطبعه بصيغة PDF.</p></div><a class="button ghost" href="/forms">العودة للنماذج</a></header><nav class="no-print"><button class="button primary" data-tab="activity">تقرير فعالية كشفية</button><button class="button ghost" data-tab="meeting">محضر اجتماع مجلس الشرف</button></nav><section id="activity-panel" class="card"><h2>تقرير فعالية كشفية</h2><form id="activity-form" class="stack"><div class="fields"><label>اسم البرنامج *<input name="title" required></label><label>المحور *<input name="axis" required></label><label>التاريخ *<input name="activityDate" type="date" required></label><label>الفئة المستهدفة<input name="target" value="كشافة فرقة المتقدم"></label><label>مسؤول التنفيذ<input name="responsible"></label><label>عدد المستفيدين<input name="count" type="number" min="1" value="24"></label><label>رابط الفيديو<input name="video" type="url"></label></div><label>الأهداف<textarea name="objectives"></textarea></label><label>وصف النشاط<textarea name="description"></textarea></label><div id="activity-qr" class="no-print"></div><div class="actions no-print"><button class="button primary" type="submit">حفظ التقرير</button><button class="button ghost" type="button" data-print>طباعة / PDF</button></div><p class="status" data-status hidden></p><p class="error" data-error hidden></p></form></section><section id="meeting-panel" class="card" hidden><h2>محضر اجتماع مجلس الشرف</h2><form id="meeting-form" class="stack"><div class="fields"><label>التاريخ *<input name="meetingDate" type="date" required></label><label>اليوم<input name="day"></label><label>المكان<input name="location" value="مدرسة النعيم الثانوية للبنين"></label><label>من<input name="start" type="time"></label><label>إلى<input name="end" type="time"></label></div><label>الحضور<textarea name="attendees"></textarea></label><label>المحاور والتوصيات<textarea name="agenda" required></textarea></label><div class="actions no-print"><button class="button primary" type="submit">حفظ المحضر</button><button class="button ghost" type="button" data-print>طباعة / PDF</button></div><p class="status" data-status hidden></p><p class="error" data-error hidden></p></form></section></main><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>
const activityPanel=document.getElementById("activity-panel"),meetingPanel=document.getElementById("meeting-panel");document.querySelectorAll("[data-tab]").forEach((button)=>button.addEventListener("click",()=>{const activity=button.dataset.tab==="activity";activityPanel.hidden=!activity;meetingPanel.hidden=activity;}));document.querySelectorAll("[data-print]").forEach((button)=>button.addEventListener("click",()=>window.print()));const activityForm=document.getElementById("activity-form");activityForm.video?.addEventListener("input",()=>{const target=document.getElementById("activity-qr");target.replaceChildren();if(activityForm.video.value&&window.QRCode)new QRCode(target,{text:activityForm.video.value,width:120,height:120});});async function submitForm(form,path,payload){const status=form.querySelector("[data-status]"),error=form.querySelector("[data-error]");status.hidden=true;error.hidden=true;const response=await fetch(path,{method:"POST",headers:{"Content-Type":"application/json"},credentials:"same-origin",body:JSON.stringify(payload)});const result=await response.json().catch(()=>({}));if(!response.ok){error.textContent=result.error||"تعذر حفظ النموذج";error.hidden=false;return;}status.textContent="تم الحفظ بنجاح";status.hidden=false;}activityForm.addEventListener("submit",(event)=>{event.preventDefault();const data=Object.fromEntries(new FormData(activityForm));const {title,axis,activityDate,...details}=data;submitForm(activityForm,"/api/reports/activity",{title,axis,activityDate,data:details});});document.getElementById("meeting-form").addEventListener("submit",(event)=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));const {meetingDate,...details}=data;submitForm(event.currentTarget,"/api/reports/meeting",{meetingDate,data:details});});
</script></body></html>
